<script setup>
import { ref } from 'vue'
import FinanceNavigation from '@/components/finance/FinanceNavigation.vue'
import CoretaxDraftEditor from '@/components/finance/CoretaxDraftEditor.vue'
import FasSelect from '@/components/ui/FasSelect.vue'
import { getFinanceTaxRegister } from '@/services/finance'
import { useFinanceLedger, financeToday } from '@/composables/useFinanceLedger'
import { reportMoney as money } from '@/utils/financeReporting'
import '@/assets/finance-ledger.css'
const selected=ref('')
const {filters,applied,data,summary,total,ready,loading,exporting,error,page,load,report,canPrevious,canNext,description}=useFinanceLedger(getFinanceTaxRegister,{query:'',date_from:financeToday().slice(0,7)+'-01',date_to:financeToday(),category:''},
 {title:'Rekap Persiapan Pajak — Faktur Penjualan',filename:'PTFAS_Rekap_Pajak.xlsx',headings:['Faktur','Tanggal','Customer','NPWP/NIK sumber','Mode','Skema','Penjualan sebelum PPN','DPP PPN sumber','PPN','Total','Revisi draft'],rows:items=>items.map(x=>[x.invoice_number,x.invoice_date,x.store_name,x.buyer_tin,x.tax_mode,x.tax_scheme,x.net_sales,x.tax_base,x.vat,x.total,x.draft_revision]),printHeadings:['Faktur / Tanggal','Customer / NPWP','Mode','Penjualan sebelum PPN','DPP PPN','PPN','Draft'],printRows:items=>items.map(x=>[x.invoice_number+' / '+x.invoice_date,x.store_name+' / '+(x.buyer_tin||'Belum diisi'),x.tax_mode,money(x.net_sales),money(x.tax_base),money(x.vat),x.draft_revision?'Revisi '+x.draft_revision:'Belum diisi']),description:s=>'PPN sumber '+money(s.vat)+' · Rekap internal, bukan SPT atau bukti pelaporan DJP'})
</script>
<template>
 <main class="finance-ledger"><header class="page-heading"><div><p class="eyebrow">Finance · Tax Center</p><h1>Pajak & Persiapan Coretax</h1><p class="muted">Telusuri faktur sumber, lengkapi identitas perpajakan, dan siapkan berkas untuk diperiksa Finance.</p></div><a class="button" href="https://coretaxdjp.pajak.go.id/" target="_blank" rel="noopener noreferrer">Buka Coretax DJP</a></header><FinanceNavigation />
 <p class="message">Rekap web, Excel dan Print/PDF tersedia. Ekspor XML mendukung subset faktur PPN domestik normal setelah pemetaan lengkap. Belum ada koneksi API DJP/PJAP; impor, validasi serta penandatanganan dilakukan di Coretax.</p><p v-if="error" class="message error" role="alert">{{ error }}</p>
 <section class="cards"><article class="card"><span>Penjualan sebelum PPN sesuai filter</span><strong>{{ ready?money(summary.net_sales):'—' }}</strong></article><article class="card"><span>DPP PPN sesuai faktur sumber</span><strong>{{ ready?money(summary.tax_base):'—' }}</strong></article><article class="card"><span>PPN faktur sumber</span><strong>{{ ready?money(summary.vat):'—' }}</strong><small>Belum dikurangi pajak masukan dan koreksi; bukan PPN kurang bayar final.</small></article></section>
 <form class="panel" @submit.prevent="load(true)"><fieldset :disabled="loading||exporting"><div class="filters"><label>Cari faktur/customer/NPWP<input v-model="filters.query" maxlength="200" type="search" /></label><label>Dari tanggal<input v-model="filters.date_from" type="date" /></label><label>Sampai tanggal<input v-model="filters.date_to" type="date" /></label><label>Perlakuan sumber<FasSelect v-model="filters.category" aria-label="Perlakuan pajak sumber"><option value="">Semua</option><option value="PPN">PPN</option><option value="NON_PPN">Non-PPN</option></FasSelect></label><div class="actions"><button class="primary" type="submit">Terapkan filter</button></div></div></fieldset></form>
 <section class="panel"><header class="panel-heading"><div><h2>Daftar faktur sumber</h2><small>{{ description(applied) }}</small></div><div class="actions"><button :disabled="!ready||loading||exporting" @click="report('excel')">Excel seluruh hasil</button><button :disabled="!ready||loading||exporting" @click="report('print')">Print / PDF seluruh hasil</button></div></header><div class="table-scroll"><table><thead><tr><th>Faktur / Tanggal</th><th>Customer / NPWP</th><th>Mode / Skema</th><th class="money">Penjualan sebelum PPN</th><th class="money">PPN</th><th>Draft internal</th><th>Aksi</th></tr></thead><tbody><tr v-for="item in data" :key="item.id"><td>{{ item.invoice_number }}<small>{{ item.invoice_date }}</small></td><td>{{ item.store_name }}<small>{{ item.buyer_tin||'Identitas belum diisi' }}</small></td><td>{{ item.tax_mode }}<small>{{ item.tax_scheme }}</small></td><td class="money">{{ money(item.net_sales) }}</td><td class="money">{{ money(item.vat) }}</td><td><span class="badge">{{ item.draft_revision?'Revisi '+item.draft_revision:'Belum diisi' }}</span><small>Belum menunjukkan status DJP</small></td><td><button :disabled="exporting" @click="selected=item.id">Siapkan draft pajak</button></td></tr><tr v-if="!data.length"><td class="empty" colspan="7">{{ loading?'Memuat…':'Belum ada faktur aktif sesuai filter.' }}</td></tr></tbody></table></div><footer class="pagination"><span>{{ total }} faktur · Halaman {{ page+1 }}</span><div class="actions"><button :disabled="!canPrevious" @click="load(false,page-1)">Sebelumnya</button><button :disabled="!canNext" @click="load(false,page+1)">Berikutnya</button></div></footer></section>
 <Teleport to="body"><CoretaxDraftEditor v-if="selected" :invoice-id="selected" @close="selected=''" @saved="load()" /></Teleport>
 </main>
</template>
